def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    new_rows = 2 * rows
    new_cols = 2 * cols
    output = [[0] * new_cols for _ in range(new_rows)]

    # TL: Identity - copy input
    for r in range(rows):
        for c in range(cols):
            output[r][c] = grid[r][c]

    # TR: Horizontal flip
    for r in range(rows):
        for c in range(cols):
            output[r][new_cols - 1 - c] = grid[r][c]

    # BL: Vertical flip  
    for r in range(rows):
        for c in range(cols):
            output[rows + r][c] = grid[rows - 1 - r][c]

    # BR: Both flips (180° rotation)
    for r in range(rows):
        for c in range(cols):
            output[rows + r][new_cols - 1 - c] = grid[rows - 1 - r][cols - 1 - c]

    return output

