def transform(grid):
    n = len(grid)
    output = [[0] * (2 * n) for _ in range(2 * n)]

    # TL: Original copy
    for i in range(n):
        for j in range(n):
            output[i][j] = grid[i][j]

    # TR: 90° counter-clockwise (new[i][j] = old[n-1-j][i])
    for i in range(n):
        for j in range(n):
            output[i][n + j] = grid[n - 1 - j][i]

    # BL: 90° clockwise (new[i][j] = old[j][n-1-i])
    for i in range(n):
        for j in range(n):
            output[n + i][j] = grid[j][n - 1 - i]

    # BR: 180° rotation (new[i][j] = old[n-1-i][n-1-j])
    for i in range(n):
        for j in range(n):
            output[n + i][n + j] = grid[n - 1 - i][n - 1 - j]

    return output

